package net.civeira.phylax.feature.observe.observedissuecomment.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.ObservedIssueComment;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.valueobject.TextVO;

class TextValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of text of observed issue comment")
  void test_text_value_holder_assign_plain_value() {
    Object holder = new Object();
    TextValueHolder<Object> value = new TextValueHolder<>(holder);
    Assertions.assertSame(holder, value.text("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getTextValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getText().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of text of observed issue comment")
  void test_text_value_holder_assign_value_object() {
    Object holder = new Object();
    TextValueHolder<Object> value = new TextValueHolder<>(holder);
    TextVO vo = TextVO.from("one");
    Assertions.assertFalse(value.getTextValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.text(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getTextValue().orElseThrow());
    Assertions.assertSame(holder, value.text(Optional.empty()));
    Assertions.assertFalse(value.getTextValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.text(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTextValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of text of observed issue comment against the original")
  void test_text_value_holder_read() {
    Object holder = new Object();
    TextValueHolder<Object> value = new TextValueHolder<>(holder);
    TextVO vo = TextVO.from("one");
    TextVO other = TextVO.from("one");
    ObservedIssueComment original = Mockito.mock(ObservedIssueComment.class);
    Mockito.when(original.getTextValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readText(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readText(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.text(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readText(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readText(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of text of observed issue comment")
  void test_text_value_holder_unset() {
    Object holder = new Object();
    TextValueHolder<Object> value = new TextValueHolder<>(holder);
    TextVO vo = TextVO.from("one");
    value.text(vo);
    Assertions.assertSame(holder, value.unsetTextIfMatches("text_other"));
    Assertions.assertTrue(value.getTextValue().isPresent(), "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTextIfMatches("text"));
    Assertions.assertFalse(value.getTextValue().isPresent(), "The field name must clear the value");
    value.text(vo);
    Assertions.assertSame(holder, value.unsetText());
    Assertions.assertFalse(value.getTextValue().isPresent(), "Unset must clear the value");
  }
}
